import { randomUUID } from 'node:crypto';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname } from 'node:path';

async function readBooks(filePath) {
  try {
    const raw = await readFile(filePath, 'utf8');
    return raw.trim() ? JSON.parse(raw) : [];
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeBooks(filePath, books) {
  await mkdir(dirname(filePath), { recursive: true });
  const tmpPath = `${filePath}.${randomUUID()}.tmp`;
  await writeFile(tmpPath, JSON.stringify(books, null, 2));
  await rename(tmpPath, filePath);
}

export function createStore(filePath) {
  return {
    async list() {
      return readBooks(filePath);
    },

    async get(id) {
      const books = await readBooks(filePath);
      return books.find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      if (!title || !title.trim()) throw new Error('Title is required');
      const books = await readBooks(filePath);
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author?.trim() || '',
        notes: notes?.trim() || '',
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await writeBooks(filePath, books);
      return book;
    },

    async update(id, changes) {
      const books = await readBooks(filePath);
      const book = books.find((b) => b.id === id);
      if (!book) return null;

      if (changes.notes !== undefined) book.notes = changes.notes;
      if (changes.title !== undefined && changes.title.trim()) book.title = changes.title.trim();
      if (changes.author !== undefined) book.author = changes.author.trim();
      if (changes.status !== undefined && ['reading', 'finished'].includes(changes.status)) {
        book.status = changes.status;
        book.finishedAt = changes.status === 'finished' ? new Date().toISOString() : null;
      }

      await writeBooks(filePath, books);
      return book;
    },
  };
}

