import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createStore } from './lib/store.mjs';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const PUBLIC_DIR = join(__dirname, 'public');
const DATA_FILE = process.env.BOOKS_DATA_FILE ?? join(__dirname, 'data', 'books.json');
const PORT = process.env.PORT ?? 3000;

const store = createStore(DATA_FILE);

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
};

function sendJson(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

async function readJsonBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString('utf8');
  if (!raw.trim()) return {};
  return JSON.parse(raw);
}

async function serveStatic(res, path) {
  const filePath = join(PUBLIC_DIR, path);
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403);
    res.end();
    return;
  }
  try {
    const contents = await readFile(filePath);
    res.writeHead(200, { 'Content-Type': MIME_TYPES[extname(filePath)] ?? 'application/octet-stream' });
    res.end(contents);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

async function handleApi(req, res, url) {
  const parts = url.pathname.split('/').filter(Boolean); // ['api', 'books', maybe id]

  if (parts.length === 2 && req.method === 'GET') {
    return sendJson(res, 200, await store.list());
  }

  if (parts.length === 2 && req.method === 'POST') {
    try {
      const body = await readJsonBody(req);
      const book = await store.add(body);
      return sendJson(res, 201, book);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  if (parts.length === 3 && req.method === 'GET') {
    const book = await store.get(parts[2]);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });
    return sendJson(res, 200, book);
  }

  if (parts.length === 3 && req.method === 'PATCH') {
    try {
      const body = await readJsonBody(req);
      const book = await store.update(parts[2], body);
      if (!book) return sendJson(res, 404, { error: 'Book not found' });
      return sendJson(res, 200, book);
    } catch (err) {
      return sendJson(res, 400, { error: err.message });
    }
  }

  sendJson(res, 404, { error: 'Not found' });
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  try {
    if (url.pathname.startsWith('/api/')) {
      return await handleApi(req, res, url);
    }

    if (url.pathname === '/' || url.pathname === '/index.html' || url.pathname.startsWith('/book/')) {
      return await serveStatic(res, 'index.html');
    }

    return await serveStatic(res, url.pathname);
  } catch (err) {
    console.error(err);
    sendJson(res, 500, { error: 'Internal server error' });
  }
});

server.listen(PORT, () => {
  console.log(`Reading tracker running at http://localhost:${PORT}`);
});

