:root {
  color-scheme: light dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

body {
  max-width: 700px;
  margin: 0 auto;
  padding: 1.5rem;
  line-height: 1.5;
}

header h1 a {
  text-decoration: none;
  color: inherit;
}

h2 {
  margin-top: 2rem;
  border-bottom: 1px solid #8884;
  padding-bottom: 0.25rem;
}

.book-list {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.book-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.6rem 0.8rem;
  border: 1px solid #8884;
  border-radius: 8px;
}

.book-row a {
  text-decoration: none;
  color: inherit;
  font-weight: 600;
}

.book-row a:hover {
  text-decoration: underline;
}

.book-row .author {
  font-weight: 400;
  opacity: 0.7;
  font-size: 0.9em;
}

.empty {
  opacity: 0.6;
  font-style: italic;
}

form.add-book {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-top: 1rem;
}

form.add-book input,
form.add-book textarea {
  font: inherit;
  padding: 0.5rem;
  border-radius: 6px;
  border: 1px solid #8884;
  background: transparent;
  color: inherit;
}

button {
  font: inherit;
  padding: 0.5rem 0.9rem;
  border-radius: 6px;
  border: 1px solid #8884;
  background: #6366f122;
