  border-radius: 999px;
  background: #8884;
  width: fit-content;
}

.badge.finished {
  background: #22c55e33;
}

.back-link {
  display: inline-block;
  margin-bottom: 0.5rem;
}

.error {
  color: #ef4444;
}

