const app = document.getElementById('app');

async function api(path, options) {
  const res = await fetch(path, {
    ...options,
    headers: { 'Content-Type': 'application/json' },
  });
  const body = await res.json().catch(() => null);
  if (!res.ok) throw new Error(body?.error ?? 'Request failed');
  return body;
}

function el(tag, props = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (key === 'text') node.textContent = value;
    else if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else node.setAttribute(key, value);
  }
  for (const child of children) node.append(child);
  return node;
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function bookRow(book) {
  const link = el('a', { href: `/book/${book.id}`, text: book.title });
  link.addEventListener('click', (e) => {
    e.preventDefault();
    navigate(`/book/${book.id}`);
  });

  const row = el('li', { class: 'book-row' }, [
    el('div', {}, [link, document.createTextNode(' '), el('span', { class: 'author', text: book.author || '' })]),
  ]);

  if (book.status === 'reading') {
    const finishBtn = el('button', { class: 'secondary', text: 'Mark finished' });
    finishBtn.addEventListener('click', async () => {
      await api(`/api/books/${book.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'finished' }) });
      renderHome();
    });
    row.append(finishBtn);
  }

  return row;
}

async function renderHome() {
  app.replaceChildren();

  let books = [];
  let loadError = null;
  try {
    books = await api('/api/books');
  } catch (err) {
    loadError = err.message;
  }

  if (loadError) {
    app.append(el('p', { class: 'error', text: `Couldn't load books: ${loadError}` }));
    return;
  }

  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  app.append(el('h2', { text: 'Currently reading' }));
  app.append(
    reading.length
      ? el('ul', { class: 'book-list' }, reading.map(bookRow))
      : el('p', { class: 'empty', text: 'Nothing yet — add a book below.' })
  );

  app.append(el('h2', { text: 'Finished' }));
  app.append(
    finished.length
      ? el('ul', { class: 'book-list' }, finished.map(bookRow))
      : el('p', { class: 'empty', text: 'No finished books yet.' })
  );

  app.append(el('h2', { text: 'Add a book' }));
  const titleInput = el('input', { name: 'title', placeholder: 'Title', required: 'true' });
  const authorInput = el('input', { name: 'author', placeholder: 'Author' });
  const notesInput = el('textarea', { name: 'notes', placeholder: 'Notes (optional)', rows: '3' });
  const submitBtn = el('button', { type: 'submit', text: 'Add book' });
  const formError = el('p', { class: 'error' });

  const form = el('form', { class: 'add-book' }, [titleInput, authorInput, notesInput, submitBtn, formError]);
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    formError.textContent = '';
    try {
      await api('/api/books', {
        method: 'POST',
        body: JSON.stringify({ title: titleInput.value, author: authorInput.value, notes: notesInput.value }),
      });
      renderHome();
    } catch (err) {
      formError.textContent = err.message;
    }
  });
  app.append(form);
}

async function renderBook(id) {
  app.replaceChildren();

  let book;
  try {
    book = await api(`/api/books/${id}`);
  } catch (err) {
    app.append(el('p', { class: 'error', text: `Couldn't load book: ${err.message}` }));
    return;
  }

  const backLink = el('a', { class: 'back-link', href: '/', text: '← Back to all books' });
  backLink.addEventListener('click', (e) => {
    e.preventDefault();
    navigate('/');
  });
  app.append(backLink);

  const container = el('div', { class: 'detail' });
  container.append(el('h2', { text: book.title }));
  if (book.author) container.append(el('p', { class: 'author', text: book.author }));
  container.append(
    el('span', {
      class: `badge${book.status === 'finished' ? ' finished' : ''}`,
      text: book.status === 'finished' ? 'Finished' : 'Currently reading',
    })
  );

  const notesLabel = el('label', { text: 'Notes' });
  const notesArea = el('textarea', { text: book.notes || '' });
  const saveBtn = el('button', { text: 'Save notes' });
  const saveStatus = el('span', {});

  saveBtn.addEventListener('click', async () => {
    saveStatus.textContent = 'Saving…';
    try {
      await api(`/api/books/${id}`, { method: 'PATCH', body: JSON.stringify({ notes: notesArea.value }) });
      saveStatus.textContent = 'Saved.';
    } catch (err) {
      saveStatus.textContent = err.message;
    }
  });

  container.append(notesLabel, notesArea, saveBtn, saveStatus);

  const actions = el('div', { class: 'actions' });
  if (book.status === 'reading') {
    const finishBtn = el('button', { text: 'Mark as finished' });
    finishBtn.addEventListener('click', async () => {
      await api(`/api/books/${id}`, { method: 'PATCH', body: JSON.stringify({ status: 'finished' }) });
      renderBook(id);
    });
    actions.append(finishBtn);
  }

  const copyBtn = el('button', { class: 'secondary', text: 'Copy link to this book' });
  copyBtn.addEventListener('click', async () => {
    await navigator.clipboard.writeText(window.location.href);
    copyBtn.textContent = 'Link copied!';
    setTimeout(() => (copyBtn.textContent = 'Copy link to this book'), 1500);
  });
  actions.append(copyBtn);

  container.append(actions);
  app.append(container);
}

function route() {
  const path = window.location.pathname;
  const bookMatch = path.match(/^\/book\/([^/]+)$/);
  if (bookMatch) {
    renderBook(decodeURIComponent(bookMatch[1]));
  } else {
    renderHome();
  }
}

function navigate(path) {
  window.history.pushState({}, '', path);
  route();
}

window.addEventListener('popstate', route);
route();

