import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createStore } from './store.mjs';

let dir;
let filePath;
let store;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-test-'));
  filePath = join(dir, 'books.json');
  store = createStore(filePath);
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

it('starts empty', async () => {
  expect(await store.list()).toEqual([]);
});

it('adds a book as currently reading', async () => {
  const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'so far so good' });
  expect(book.status).toBe('reading');
  expect(book.finishedAt).toBeNull();
  expect(await store.list()).toEqual([book]);
});

it('rejects a book with no title', async () => {
  await expect(store.add({ title: '  ' })).rejects.toThrow(/title/i);
});

it('marks a book finished and stamps finishedAt', async () => {
  const book = await store.add({ title: 'Dune' });
  const updated = await store.update(book.id, { status: 'finished' });
  expect(updated.status).toBe('finished');
  expect(updated.finishedAt).not.toBeNull();
});

it('updates notes without touching status', async () => {
  const book = await store.add({ title: 'Dune' });
  const updated = await store.update(book.id, { notes: 'new notes' });
  expect(updated.notes).toBe('new notes');
  expect(updated.status).toBe('reading');
});

it('returns null when updating a missing book', async () => {
  expect(await store.update('does-not-exist', { notes: 'x' })).toBeNull();
});

it('persists across store instances', async () => {
  await store.add({ title: 'Dune' });
  const reopened = createStore(filePath);
  expect(await reopened.list()).toHaveLength(1);
});

